// Obtain the library version string and assert basic invariants
const char *ver = mdb_get_version();
// Returned pointer is library-owned; ensure it looks usable
FUZZ_ASSERT(ver != nullptr, "mdb_get_version returned NULL");
// Optional sanity: non-empty string
if (!ver[0]) { FUZZ_BAIL(); }
// Validation: Preconditions satisfied (none). Return value checked and not freed.

// Choose a page number. We can't know valid range; rely on function to signal errors.
unsigned long pg = (unsigned long)(*FUZZ_PARAM(unsigned int));
ssize_t n = mdb_read_pg(mdb, pg);
// Track whether a usable page buffer is now available
if (n > 0) {
    FUZZ_SET_ATTR_INT(mdb, "page_loaded", 1);
    FUZZ_SET_ATTR_INT(mdb, "page_bytes", (int)n);
    // Current buffer is primary after read
    FUZZ_SET_ATTR_INT(mdb, "current_buf", 0);
} else {
    // Error or short read; mark as not loaded to prevent invalid pg_get_* use downstream
    FUZZ_SET_ATTR_INT(mdb, "page_loaded", 0);
    FUZZ_SET_ATTR_INT(mdb, "page_bytes", 0);
}
// Validation: Input handle presumed valid from pool. We preserve mdb by returning it; errors are tolerated via return code.

unsigned long pg = (unsigned long)(*FUZZ_PARAM(unsigned int));
ssize_t n = mdb_read_alt_pg(mdb, pg);
if (n > 0) {
    FUZZ_SET_ATTR_INT(mdb, "alt_page_loaded", 1);
    FUZZ_SET_ATTR_INT(mdb, "alt_page_bytes", (int)n);
    // Do not change current_buf; swap controls which buffer is current
} else {
    FUZZ_SET_ATTR_INT(mdb, "alt_page_loaded", 0);
    FUZZ_SET_ATTR_INT(mdb, "alt_page_bytes", 0);
}
// Validation: Handle kept alive; attributes updated for downstream buffer-aware stubs.

// Create a random buffer and safe offset
std::string buf = FUZZ_PARAM_STR();
size_t need = 1;
if (buf.size() < need) { FUZZ_BAIL(); }
int max_off = (int)(buf.size() - need);
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile unsigned char v = mdb_get_byte((void*)buf.data(), offset);
(void)v;
// Validation: Buffer bounds enforced; no persistent outputs.

std::string buf = FUZZ_PARAM_STR();
size_t need = 2;
if (buf.size() < need) { FUZZ_BAIL(); }
int max_off = (int)(buf.size() - need);
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile int v = mdb_get_int16((void*)buf.data(), offset);
(void)v;
// Validation: Bounds enforced; OK.

std::string buf = FUZZ_PARAM_STR();
size_t need = 4;
if (buf.size() < need) { FUZZ_BAIL(); }
int max_off = (int)(buf.size() - need);
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile long v = mdb_get_int32((void*)buf.data(), offset);
(void)v;
// Validation: Bounds enforced; OK.

std::string buf = FUZZ_PARAM_STR();
size_t need = 4;
if (buf.size() < need) { FUZZ_BAIL(); }
int max_off = (int)(buf.size() - need);
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile long v = mdb_get_int32_msb((void*)buf.data(), offset);
(void)v;
// Validation: Bounds enforced; OK.

std::string buf = FUZZ_PARAM_STR();
size_t need = 4;
if (buf.size() < need) { FUZZ_BAIL(); }
int max_off = (int)(buf.size() - need);
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile float v = mdb_get_single((void*)buf.data(), offset);
(void)v;
// Validation: Bounds enforced; OK.

std::string buf = FUZZ_PARAM_STR();
size_t need = 8;
if (buf.size() < need) { FUZZ_BAIL(); }
int max_off = (int)(buf.size() - need);
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile double v = mdb_get_double((void*)buf.data(), offset);
(void)v;
// Validation: Bounds enforced; OK.

// Require a loaded current page and a known byte count for safe offset selection
int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes <= 0) { FUZZ_BAIL(); }
int need = 1;
if (nbytes < need) { FUZZ_BAIL(); }
int max_off = nbytes - need;
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile unsigned char v = mdb_pg_get_byte(mdb, offset);
(void)v;
// Validation: Enforced precondition of loaded page; safe offset computed from tracked size.

int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes < 2) { FUZZ_BAIL(); }
int max_off = nbytes - 2;
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile int v = mdb_pg_get_int16(mdb, offset);
(void)v;
// Validation: Safe slice within page buffer; handle returned to pool.

int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes < 4) { FUZZ_BAIL(); }
int max_off = nbytes - 4;
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile long v = mdb_pg_get_int32(mdb, offset);
(void)v;
// Validation: Safe offset selection; OK.

int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes < 4) { FUZZ_BAIL(); }
int max_off = nbytes - 4;
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile float v = mdb_pg_get_single(mdb, offset);
(void)v;
// Validation: Preconditions enforced; handle output preserved.

int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes < 8) { FUZZ_BAIL(); }
int max_off = nbytes - 8;
int offset = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile double v = mdb_pg_get_double(mdb, offset);
(void)v;
// Validation: Preconditions enforced; handle returned.

const char *filename = FUZZ_PARAM_FILENAME();
// Generate valid flags subset
MdbFileFlags flags = (MdbFileFlags)((*FUZZ_PARAM(unsigned int)) & 0x1); // MDB_NOFLAGS or MDB_WRITABLE
MdbHandle *mdb = mdb_open(filename, flags);
if (!mdb) { FUZZ_BAIL(); }
// Initialize useful attributes for downstream stubs
FUZZ_SET_ATTR_INT(mdb, "page_loaded", 0);
FUZZ_SET_ATTR_INT(mdb, "alt_page_loaded", 0);
FUZZ_SET_ATTR_INT(mdb, "page_bytes", 0);
FUZZ_SET_ATTR_INT(mdb, "alt_page_bytes", 0);
FUZZ_SET_ATTR_INT(mdb, "current_buf", 0);
// Validation: On success, we export a persistent MdbHandle. Failure cases bail to keep outputs non-null.

// Construct an in-memory image; ensure non-trivial size for plausibility
std::string img = FUZZ_PARAM_STR();
if (img.size() < 512) { FUZZ_BAIL(); }
MdbFileFlags flags = (MdbFileFlags)((*FUZZ_PARAM(unsigned int)) & 0x1); // MDB_NOFLAGS or MDB_WRITABLE
MdbHandle *mdb = mdb_open_buffer((void*)img.data(), img.size(), flags);
if (!mdb) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(mdb, "page_loaded", 0);
FUZZ_SET_ATTR_INT(mdb, "alt_page_loaded", 0);
FUZZ_SET_ATTR_INT(mdb, "page_bytes", 0);
FUZZ_SET_ATTR_INT(mdb, "alt_page_bytes", 0);
FUZZ_SET_ATTR_INT(mdb, "current_buf", 0);
// Validation: Creates a handle from an image; bails if library rejects image to ensure non-null output.

// Close frees the handle; do not return it
mdb_close(mdb);
// Validation: Ownership transferred to library; no outputs to avoid double-free.

MdbHandle *mdb_clone = mdb_clone_handle(mdb);
if (!mdb_clone) { FUZZ_BAIL(); }
// Mirror key attributes so downstream pg_get_* can work with either handle
int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
FUZZ_SET_ATTR_INT(mdb_clone, "page_loaded", loaded);
FUZZ_SET_ATTR_INT(mdb_clone, "page_bytes", nbytes);
FUZZ_SET_ATTR_INT(mdb_clone, "alt_page_loaded", FUZZ_GET_ATTR_INT(mdb, "alt_page_loaded"));
FUZZ_SET_ATTR_INT(mdb_clone, "alt_page_bytes", FUZZ_GET_ATTR_INT(mdb, "alt_page_bytes"));
FUZZ_SET_ATTR_INT(mdb_clone, "current_buf", FUZZ_GET_ATTR_INT(mdb, "current_buf"));
// Validation: Both original and clone are returned; non-null enforced.

// Perform swap
mdb_swap_pgbuf(mdb);
// Reflect swap in attributes: promote alt_* to primary if available
int alt_loaded = FUZZ_GET_ATTR_INT(mdb, "alt_page_loaded");
int alt_bytes = FUZZ_GET_ATTR_INT(mdb, "alt_page_bytes");
int cur_loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int cur_bytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
// Swap the metadata to keep pg_get_* consistent with current primary buffer
FUZZ_SET_ATTR_INT(mdb, "page_loaded", alt_loaded);
FUZZ_SET_ATTR_INT(mdb, "page_bytes", alt_bytes);
FUZZ_SET_ATTR_INT(mdb, "alt_page_loaded", cur_loaded);
FUZZ_SET_ATTR_INT(mdb, "alt_page_bytes", cur_bytes);
// Toggle indicator
int current_buf = FUZZ_GET_ATTR_INT(mdb, "current_buf");
FUZZ_SET_ATTR_INT(mdb, "current_buf", current_buf ? 0 : 1);
// Validation: State updated to keep downstream read offsets safe after swap.

// Free catalog-related allocations; handle remains valid
mdb_free_catalog(mdb);
// Optionally clear any soft catalog-related attributes (none tracked here)
// Validation: Input preserved and returned to pool; safe to continue using handle.

// Ensure we have an open/valid handle from the pool (assumed by runtime)
// Choose an object type to read; we don't know valid enum range, so use fuzzed int directly
int obj_type = (int)(*FUZZ_PARAM(unsigned int));
GPtrArray *arr = mdb_read_catalog(mdb, obj_type);
// Record that catalog data may now be available on this handle for downstream calls
if (arr) {
    FUZZ_SET_ATTR_INT(mdb, "catalog_loaded", 1);
    FUZZ_SET_ATTR_INT(mdb, "catalog_obj_type", obj_type);
} else {
    // Catalog read failed; mark as not loaded
    FUZZ_SET_ATTR_INT(mdb, "catalog_loaded", 0);
}
// We return the handle as persistent output; the GPtrArray (if any) is managed by library/handle and can be freed later via mdb_free_catalog.

// Ensure catalog exists; if not, try to read it for any type
if (!FUZZ_GET_ATTR_INT(mdb, "catalog_loaded")) {
    int fallback_type = (int)(*FUZZ_PARAM(unsigned int));
    (void)mdb_read_catalog(mdb, fallback_type);
    FUZZ_SET_ATTR_INT(mdb, "catalog_loaded", 1);
}
// Use a fuzzed name; API allows not found (NULL), but we need a non-null output entry, so bail if not found
std::string name = FUZZ_PARAM_STR();
MdbCatalogEntry *entry = mdb_get_catalogentry_by_name(mdb, name.c_str());
if (!entry) { FUZZ_BAIL(); }
// Track provenance for safety in downstream stubs
FUZZ_SET_ATTR_PTR(entry, "from_handle", (void*)mdb);
// Return both the handle (still valid) and the found catalog entry.

// Dump any object type; choose fuzzed integer which library will interpret
int obj_type = (int)(*FUZZ_PARAM(unsigned int));
mdb_dump_catalog(mdb, obj_type);
// No additional outputs; handle remains valid.

// Exercise mapping with a fuzzed enum value
int obj_type = (int)(*FUZZ_PARAM(unsigned int));
const char *s = mdb_get_objtype_string(obj_type);
// Returned string is library-owned; basic sanity
FUZZ_ASSERT(s != nullptr, "mdb_get_objtype_string returned NULL");

// Allocate a tabledef for this catalog entry
MdbTableDef *table = mdb_alloc_tabledef(entry);
if (!table) { FUZZ_BAIL(); }
// Track association for downstream validation
FUZZ_SET_ATTR_PTR(table, "catalog_entry", (void*)entry);
// Return allocated tabledef.

// Free the table definition; after this, it must not be used
mdb_free_tabledef(table);
// No outputs returned to avoid use-after-free.

// Fully read the table definition and metadata for this entry
MdbTableDef *table = mdb_read_table(entry);
if (!table) { FUZZ_BAIL(); }
// Track association
FUZZ_SET_ATTR_PTR(table, "catalog_entry", (void*)entry);
// Return initialized tabledef.

// Choose a table name and object type; API requires existing name for success
std::string tname = FUZZ_PARAM_STR();
int obj_type = (int)(*FUZZ_PARAM(unsigned int));
MdbTableDef *table = mdb_read_table_by_name(mdb, (gchar*)tname.c_str(), obj_type);
if (!table) { FUZZ_BAIL(); }
// Track provenance
FUZZ_SET_ATTR_PTR(table, "from_handle", (void*)mdb);
// Return the tabledef for downstream use.

// columns is expected to be a GPtrArray* produced by mdb_read_columns
// We cannot name GPtrArray in the harness types list; treat it opaquely and cast here.
if (!columns) { FUZZ_BAIL(); }
mdb_free_columns((GPtrArray*)columns);
// No outputs; array is freed.

// Read column definitions for this table
GPtrArray *cols = mdb_read_columns(table);
if (!cols) { FUZZ_BAIL(); }
// Return the table (still valid) and the opaque columns array for downstream mdb_free_columns
void *columns = (void*)cols;
// Attribute to link for provenance if needed later
FUZZ_SET_ATTR_PTR(table, "last_columns", columns);

// Dump a human-readable representation of the object described by this catalog entry
mdb_table_dump(entry);
// Entry remains valid; return it to the pool.

// Ensure a page is loaded and we know its size
int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes < 1) { FUZZ_BAIL(); }
int max_off = nbytes - 1;
int cur = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
// Perform the read advancing cur_pos
volatile guint8 v = read_pg_if_8(mdb, &cur);
(void)v;
// Basic postcondition: cur should have advanced by 1 within bounds
FUZZ_ASSERT(cur >= 0 && cur <= nbytes, "cur_pos advanced out of bounds after read_pg_if_8");

int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes < 2) { FUZZ_BAIL(); }
int max_off = nbytes - 2;
int cur = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
volatile guint16 v = read_pg_if_16(mdb, &cur);
(void)v;
FUZZ_ASSERT(cur >= 0 && cur <= nbytes, "cur_pos advanced out of bounds after read_pg_if_16");

int loaded = FUZZ_GET_ATTR_INT(mdb, "page_loaded");
int nbytes = FUZZ_GET_ATTR_INT(mdb, "page_bytes");
if (!loaded || nbytes < 4) { FUZZ_BAIL(); }
int max_off = nbytes - 4;
int cur = max_off ? ((int)(*FUZZ_PARAM(unsigned int)) % (max_off + 1)) : 0;
